def pays_depuis_adresse(apps, schema_editor):
    """Initialise Societe.pays depuis le code pays de l'adresse de la société (BE à défaut)."""
    Societe = apps.get_model("societe", "Societe")
    for societe in Societe.objects.select_related("adresse").all():
        code = ((getattr(societe.adresse, "code_pays", "") or "BE").strip()[:2]).upper()
        if code == "EL":
            code = "GR"
        if code not in PAYS_GERES:
            code = "BE"
        if societe.pays != code:
            Societe.objects.filter(pk=societe.pk).update(pays=code)


